-- Reviewed owner decision 2026-11-12: preserve delivery on both stores.
-- R2 is temporary holdover. No release authority is shipped here: a separately
-- reviewed command/migration must prove NAS copies, completed stitching and
-- validated NAS serving before releasing any R2 hold.
SELECT pg_advisory_xact_lock(7343226011103);
SELECT pg_advisory_xact_lock(7343226011101);
CREATE TABLE delivery_keep_holds (
 bucket text NOT NULL, object_key text NOT NULL, etag text NOT NULL CHECK(etag<>''),
 size_bytes bigint NOT NULL CHECK(size_bytes>0), recording_id bigint,
 kind text NOT NULL, sha256 text NOT NULL DEFAULT '', relative_path text NOT NULL DEFAULT '',
 imported_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(bucket,object_key)
);
CREATE INDEX delivery_keep_recording ON delivery_keep_holds(recording_id);
CREATE INDEX delivery_keep_content ON delivery_keep_holds(sha256,size_bytes) WHERE sha256<>'';
-- Exact input SHA256 4777b55af3271aaf34faf4ffd769751914b0255186a73191cb59d36ec4d8eaf9

-- Exact assembly inputs from SHA-verified public growth.json (the public
-- serving registry owns this metadata). Raw dependencies are its DB closure.
CREATE TABLE delivery_keep_output_dependencies(output_id bigint PRIMARY KEY,recording_id bigint NOT NULL);
CREATE TABLE delivery_nas_source_holds(clip_id bigint PRIMARY KEY);
CREATE FUNCTION refresh_delivery_nas_source_holds() RETURNS void LANGUAGE sql AS $$
 SELECT c.id FROM recording_clips c JOIN delivery_keep_holds h ON h.bucket=c.bucket AND h.object_key=c.object_key
 UNION SELECT unnest(o.source_clip_ids) FROM recording_collation_outputs o JOIN delivery_keep_holds h ON h.object_key=o.object_key
 UNION SELECT unnest(o.source_clip_ids) FROM recording_collation_outputs o JOIN recording_collation_hours h ON h.id=o.collation_hour_id JOIN delivery_keep_output_dependencies d ON d.output_id=o.id AND d.recording_id=h.recording_id
 ON CONFLICT DO NOTHING
$$;
SELECT refresh_delivery_nas_source_holds();

CREATE FUNCTION delivery_nas_held(k text,i bigint,p text,sha text,n bigint) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM delivery_keep_holds h WHERE (h.relative_path<>'' AND h.relative_path IN (p,regexp_replace(p,'^joined/','')))
 OR (h.sha256<>'' AND h.sha256=sha AND h.size_bytes=n))
 OR (k='raw' AND (EXISTS(SELECT 1 FROM delivery_nas_source_holds r WHERE r.clip_id=i) OR EXISTS(SELECT 1 FROM recording_clips c JOIN delivery_keep_holds h ON h.bucket=c.bucket AND h.object_key=c.object_key WHERE c.id=i)))
 OR (k='collated' AND EXISTS(SELECT 1 FROM recording_collation_outputs o WHERE o.id=i AND
 (EXISTS(SELECT 1 FROM delivery_keep_holds h WHERE h.object_key=o.object_key)
 OR EXISTS(SELECT 1 FROM delivery_keep_output_dependencies d JOIN recording_collation_hours h ON h.recording_id=d.recording_id WHERE d.output_id=o.id AND h.id=o.collation_hour_id)
 OR EXISTS(SELECT 1 FROM delivery_nas_source_holds r WHERE r.clip_id=ANY(o.source_clip_ids)))))
$$;

CREATE FUNCTION guard_delivery_hold_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR ROW(NEW.bucket,NEW.object_key,NEW.etag,NEW.size_bytes,NEW.recording_id,NEW.kind)
 IS DISTINCT FROM ROW(OLD.bucket,OLD.object_key,OLD.etag,OLD.size_bytes,OLD.recording_id,OLD.kind)
 OR (OLD.sha256<>'' AND NEW.sha256<>OLD.sha256) OR (OLD.relative_path<>'' AND NEW.relative_path<>OLD.relative_path) THEN
 RAISE EXCEPTION 'delivery keep hold requires separately reviewed release/migration'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER delivery_hold_identity BEFORE UPDATE OR DELETE ON delivery_keep_holds FOR EACH ROW EXECUTE FUNCTION guard_delivery_hold_identity();

CREATE FUNCTION guard_delivery_nas_permit() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE x jsonb; BEGIN
 IF NEW.state='delete_issued' THEN
 x:=NEW.item;
 IF x IS NULL THEN SELECT manifest->(NEW.ordinal-1) INTO x FROM nas_cleanup_plans WHERE id=NEW.plan_id; END IF;
 IF delivery_nas_held(x->>'kind',(x->>'source_id')::bigint,x->>'relative_path',x->>'sha256',(x->>'size_bytes')::bigint) THEN
 RAISE EXCEPTION 'DELIVERY KEEP HOLD: NAS deletion forbidden'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER delivery_nas_permit BEFORE INSERT OR UPDATE ON nas_cleanup_items FOR EACH ROW EXECUTE FUNCTION guard_delivery_nas_permit();

-- The seed must not race a live NAS unlink capability or an unresolved R2
-- deletion intent. Migration takes the same admission/public fences as import.
SELECT pg_advisory_xact_lock(7343226011103);
SELECT pg_advisory_xact_lock(7343226011101);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM nas_cleanup_items i JOIN nas_cleanup_plans p ON p.id=i.plan_id WHERE i.state='delete_issued' AND i.permit_expires_at>clock_timestamp()
 AND delivery_nas_held(coalesce(i.item,p.manifest->(i.ordinal-1))->>'kind',(coalesce(i.item,p.manifest->(i.ordinal-1))->>'source_id')::bigint,coalesce(i.item,p.manifest->(i.ordinal-1))->>'relative_path',coalesce(i.item,p.manifest->(i.ordinal-1))->>'sha256',(coalesce(i.item,p.manifest->(i.ordinal-1))->>'size_bytes')::bigint)) THEN
 RAISE EXCEPTION 'delivery hold import must wait for outstanding deletion authority to reconcile'; END IF;
END $$;

CREATE FUNCTION guard_delivery_source_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM delivery_nas_source_holds WHERE clip_id=OLD.id)
 AND (TG_OP='DELETE' OR ROW(NEW.recording_id,NEW.object_key,NEW.bucket,NEW.sha256,NEW.size_bytes,NEW.display_path,NEW.clip_start_at,NEW.clip_end_at) IS DISTINCT FROM ROW(OLD.recording_id,OLD.object_key,OLD.bucket,OLD.sha256,OLD.size_bytes,OLD.display_path,OLD.clip_start_at,OLD.clip_end_at)) THEN
 RAISE EXCEPTION 'DELIVERY KEEP HOLD: NAS dependency identity immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
END $$;
CREATE TRIGGER delivery_source_identity BEFORE UPDATE OR DELETE ON recording_clips FOR EACH ROW EXECUTE FUNCTION guard_delivery_source_identity();
CREATE FUNCTION guard_delivery_dependency_hold() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'delivery dependency holds require separately reviewed release/migration';END $$;
CREATE TRIGGER delivery_source_hold_immutable BEFORE UPDATE OR DELETE ON delivery_nas_source_holds FOR EACH ROW EXECUTE FUNCTION guard_delivery_dependency_hold();

CREATE FUNCTION guard_delivery_output_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (EXISTS(SELECT 1 FROM delivery_keep_holds WHERE object_key=OLD.object_key) OR EXISTS(SELECT 1 FROM delivery_keep_output_dependencies d JOIN recording_collation_hours h ON h.recording_id=d.recording_id WHERE d.output_id=OLD.id AND h.id=OLD.collation_hour_id))
 AND (TG_OP='DELETE' OR ROW(NEW.object_key,NEW.nas_relative_path,NEW.sha256,NEW.size_bytes,NEW.source_clip_ids)
 IS DISTINCT FROM ROW(OLD.object_key,OLD.nas_relative_path,OLD.sha256,OLD.size_bytes,OLD.source_clip_ids)) THEN
 RAISE EXCEPTION 'DELIVERY KEEP HOLD: joined output identity immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
END $$;
CREATE TRIGGER delivery_output_identity BEFORE UPDATE OR DELETE ON recording_collation_outputs FOR EACH ROW EXECUTE FUNCTION guard_delivery_output_identity();
CREATE FUNCTION guard_delivery_nas_plan() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (TG_OP='INSERT' OR NEW.mode='enabled') AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.manifest) x
 WHERE delivery_nas_held(x->>'kind',(x->>'source_id')::bigint,x->>'relative_path',x->>'sha256',(x->>'size_bytes')::bigint)) THEN
 RAISE EXCEPTION 'DELIVERY KEEP HOLD: NAS plan contains protected identity'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER delivery_nas_plan BEFORE INSERT OR UPDATE ON nas_cleanup_plans FOR EACH ROW EXECUTE FUNCTION guard_delivery_nas_plan();
CREATE TRIGGER delivery_output_dependency_immutable BEFORE UPDATE OR DELETE ON delivery_keep_output_dependencies FOR EACH ROW EXECUTE FUNCTION guard_delivery_dependency_hold();
